        if (n % 2 === 0) return eq + 'хоёр шийд $x=\\pm' + rt + (ex ? '=\\pm ' : '\\approx\\pm ') + s + '$; арифметик язгуур $' + rt + (ex ? '=' : '\\approx ') + s + '$.';
        return eq + 'ганц шийд $x=' + rt + (ex ? '=' : '\\approx ') + (a < 0 ? '-' : '') + s + '$' + (a < 0 ? ' — сондгой зэргийн язгуур сөрөг тооноос ч гарна.' : '.');
