        return (k > 0 ? '$' + pos + '$' : '$8^{-' + e + '}=\\dfrac{1}{8^{' + e + '}}=\\dfrac{1}{' + v + '}$') + ' — илтгэгчийг гуравны нэгээр өсгөх бүрт утга $2$ дахин өснө.';
