        if (s < R) return h + '$' + s + '\\lt ' + R + '$ — $M$ тойргийн **дотор**.';
        if (s === R) return h + 'тэнцүү — $M$ тойрог **дээр**.';
        return h + '$' + s + '\\gt ' + R + '$ — $M$ тойргийн **гадна**.';
