        return '$f(' + n419(x) + ')=f(' + n419(x2) + ')=' + n419(y) + '$: $A$ ба $B$ ижил өндөрт.\nДундаж цэгийн абсцисс $\\dfrac{' + n419(x) + '+' + U.par(n419(x2)) + '}{2}=2$ — тэгш хэмийн тэнхлэг $x=2$.';
