          bad: { m: 'y=\\left(\\dfrac{1}{2}\\right)^{-x}\\ \\ \\text{буурна}', n: 'Суурь $\\dfrac{1}{2}\\lt 1$ гэж шууд дүгнэсэн.' },
          good: { m: '\\left(\\dfrac{1}{2}\\right)^{-x}=\\left(2^{-1}\\right)^{-x}=2^{x}\\ \\ \\text{өснө}', n: '$\\dfrac{1}{2}=2^{-1}$ гэж бичвэл илтгэгчүүд үржигдэж, суурь нь $2\\gt 1$ болно.' },
