      function lab437(d) { const t = d * Math.PI / 180, c = Math.cos(t), s = Math.sin(t); return { dx: 14 * c || 0.01, dy: -14 * s + 5 || 0.01, la: c < -0.35 ? 'end' : c > 0.35 ? 'start' : 'middle' }; }

