            f: [],
            lines: function (P) {
              const dx = P.x - A441[0], dy = P.y - A441[1];
              if (!dx && !dy) return [];
              return [[A441[0], A441[1], P.x, A441[1], C.OR, 1], [P.x, A441[1], P.x, P.y, C.OR, 1]].concat(arrow441(0, 0, dx, dy, C.T), arrow441(A441[0], A441[1], P.x, P.y, C.V));
            },
