          bad: { m: '13,\\ 7,\\ 21,\\ 9,\\ \\underline{16},\\ 5,\\ 11,\\ 18,\\ 10\\ \\Rightarrow\\ Q_2=16', n: 'Эрэмбэлээгүй өгөгдлийн голын тоог авсан.' },
          good: { m: '5,\\ 7,\\ 9,\\ 10,\\ \\underline{11},\\ 13,\\ 16,\\ 18,\\ 21\\ \\Rightarrow\\ Q_2=11', n: 'Эхлээд өсөх дарааллаар эрэмбэлж, дараа нь голын гишүүнийг авна.' },
