          p: ['$O$ төвтэй тойргийн $AOB$ төв өнцөг $\\alpha$. Ягаан — $AB$ **нум**, хоёр радиус ба нумаар хүрээлэгдсэн хэсэг — **сектор**, $AB$ хөвч ба нумаар хүрээлэгдсэн шар хэсэг — **сегмент**.'],
